//! 📝️ Incremental, source-bound PNG text metadata reconstruction.
use super::{be,invalid,PngDecodeError,PngInflater};
use semio_framework_deflate::{Inflater,InflateOutcome,RetainedInflateCloseStep};
use semio_framework_value::retained_clone::{RetainedCloneGrant,RetainedCloneProgress};
use semio_framework_value::RetirementDemand;
use std::mem::size_of;

#[derive(Default,semio_framework_value::RetireOwned)]
struct Utf8{remaining:u8,low:u8,high:u8}
impl Utf8{
 fn byte(&mut self,b:u8)->Result<(),PngDecodeError>{if self.remaining!=0{if b<self.low||b>self.high{return Err(invalid("Invalid PNG text UTF-8"))}self.remaining-=1;self.low=0x80;self.high=0xbf;return Ok(())}match b{0..=0x7f=>{},0xc2..=0xdf=>{self.remaining=1;self.low=0x80;self.high=0xbf},0xe0=>{self.remaining=2;self.low=0xa0;self.high=0xbf},0xe1..=0xec|0xee..=0xef=>{self.remaining=2;self.low=0x80;self.high=0xbf},0xed=>{self.remaining=2;self.low=0x80;self.high=0x9f},0xf0=>{self.remaining=3;self.low=0x90;self.high=0xbf},0xf1..=0xf3=>{self.remaining=3;self.low=0x80;self.high=0xbf},0xf4=>{self.remaining=3;self.low=0x80;self.high=0x8f},_=>return Err(invalid("Invalid PNG text UTF-8"))}Ok(())}
 fn finish(&self)->Result<(),PngDecodeError>{if self.remaining==0{Ok(())}else{Err(invalid("Truncated PNG text UTF-8"))}}
}

/// 📚️ Owns ordered text results while borrowing only the validated decoder's immutable source.
#[derive(semio_framework_value::RetireOwned)]
pub(super) struct PngTextState{
 phase:&'static str,at:usize,end:usize,next:usize,kind:[u8;4],count:usize,maximum:usize,owned:usize,
 key_start:usize,key_end:usize,key_length:usize,value_start:usize,value_length:usize,cursor:usize,
 flag:u8,utf8:Utf8,rows:Vec<(String,String)>,key:Vec<u8>,value:Vec<u8>,inflater:Option<PngInflater>,
 z_header:[u8;2],z_header_at:usize,z_cursor:usize,pending:Option<u8>,adler_a:u32,adler_b:u32,copying:bool,
 last_progress:RetainedCloneProgress,last_work:u64,partial_capacity:usize,partial_copy:usize,failed:Option<PngDecodeError>,
}
impl PngTextState{
 pub(super) fn new(maximum:usize)->Self{Self{phase:"scan",at:8,end:0,next:0,kind:[0;4],count:0,maximum,owned:0,key_start:0,key_end:0,key_length:0,value_start:0,value_length:0,cursor:0,flag:0,utf8:Utf8::default(),rows:Vec::new(),key:Vec::new(),value:Vec::new(),inflater:None,z_header:[0;2],z_header_at:0,z_cursor:0,pending:None,adler_a:1,adler_b:0,copying:false,last_progress:Default::default(),last_work:0,partial_capacity:0,partial_copy:0,failed:None}}
 pub(super) fn done(&self)->bool{self.phase=="done"}
 pub(super) fn transferred(&self)->bool{self.phase=="transferred"}
 pub(super) fn last_progress(&self)->RetainedCloneProgress{self.last_progress}
 pub(super) fn last_work(&self)->u64{self.last_work}
 pub(super) fn clear_turn(&mut self){self.last_progress=Default::default();self.last_work=0}
 fn allocation(&self,bytes:usize)->Result<usize,PngDecodeError>{if self.owned.checked_add(bytes).is_none_or(|total|total>self.maximum){Err(invalid("PNG text exceeds original ownership limit"))}else{Ok(bytes)}}
 pub(super) fn demand(&self)->Result<RetirementDemand,PngDecodeError>{let capacity=match self.phase{"rows"=>self.count.checked_mul(size_of::<(String,String)>()).ok_or(invalid("PNG text row extent overflow"))?,"key-allocation"=>self.key_length,"value-allocation"=>self.value_length,"inflate"=>self.inflater.as_ref().and_then(|x|x.next_retained_allocation_bytes()).unwrap_or(0),_=>0};if self.phase=="inflate-close"{return Ok(self.inflater.as_ref().map_or(Default::default(),|x|if x.retained_terminal_is_empty(){RetirementDemand{depth:1,..Default::default()}}else{x.retained_retirement_demands()}))}Ok(RetirementDemand{copy_bytes:match self.phase{"copy-key"|"copy-value"=>2,"inflate"=>size_of::<PngInflater>()+3,"zlib-header"=>size_of::<PngInflater>()+1,"emit"=>size_of::<(String,String)>(),_=>0},capacity_bytes:self.allocation(capacity)?,depth:1,..Default::default()})}
 fn text_byte(&mut self,b:u8)->Result<(),PngDecodeError>{if !self.copying{let increment=if self.kind==*b"iTXt"||b<128{1}else{2};let transient=self.inflater.as_ref().map_or(0,|owner|owner.retained_allocated_bytes());let permanent=self.owned.saturating_sub(transient);if permanent.checked_add(self.key_length).and_then(|n|n.checked_add(self.value_length)).and_then(|n|n.checked_add(increment)).is_none_or(|n|n>self.maximum){return Err(invalid("PNG text exceeds original ownership limit"))}}if self.kind==*b"iTXt"{self.utf8.byte(b)?;if self.copying{self.value.push(b)}else{self.value_length=self.value_length.checked_add(1).ok_or(invalid("PNG text extent overflow"))?}}else if self.copying{if b<128{self.value.push(b)}else{self.value.push(0xc0|(b>>6));self.value.push(0x80|(b&63))}}else{self.value_length=self.value_length.checked_add(if b<128{1}else{2}).ok_or(invalid("PNG text extent overflow"))?}Ok(())}
 fn start_zlib(&mut self){self.z_cursor=self.value_start;self.z_header_at=0;self.pending=None;self.adler_a=1;self.adler_b=0;self.utf8=Utf8::default();self.phase="zlib-header"}
 fn after_value(&mut self)->Result<(),PngDecodeError>{if self.kind==*b"iTXt"{self.utf8.finish()?}if self.copying{self.phase="emit"}else{self.phase="key-allocation"}Ok(())}
 fn reserve<T>(value:&mut Vec<T>,count:usize)->Result<usize,PngDecodeError>{if count==0{return Ok(0)}value.try_reserve_exact(count).map_err(|_|invalid("PNG text allocation refused"))?;Ok(value.capacity()*size_of::<T>())}
 fn step(&mut self,source:&[u8],grant:RetainedCloneGrant)->Result<RetainedCloneProgress,PngDecodeError>{let mut p=RetainedCloneProgress{copied_items:1,..Default::default()};match self.phase{
  "scan"=>{let end=self.at.checked_add(12).ok_or(invalid("PNG text chunk extent overflow"))?;if end>source.len(){return Err(invalid("PNG text source truncated"))}let size=be(source,self.at)as usize;let next=end.checked_add(size).filter(|end|*end<=source.len()).ok_or(invalid("PNG text chunk extent invalid"))?;let kind=&source[self.at+4..self.at+8];if matches!(kind,b"tEXt"|b"zTXt"|b"iTXt"){self.count=self.count.checked_add(1).ok_or(invalid("PNG text count overflow"))?}self.at=next;if kind==b"IEND"{self.at=8;self.phase="rows"}},
  "rows"=>{let allocated=Self::reserve(&mut self.rows,self.count)?;self.partial_capacity=allocated;self.owned+=allocated;if allocated>grant.maximum_capacity_bytes||self.owned>self.maximum{return Err(invalid("PNG text row allocation exceeded its grant"))}p.retained_capacity_bytes=allocated;self.phase="chunk"},
  "chunk"=>{let size=be(source,self.at)as usize;self.kind=source[self.at+4..self.at+8].try_into().unwrap();self.end=self.at+8+size;self.next=self.end+4;if self.kind==*b"IEND"{self.phase="done"}else if matches!(&self.kind,b"tEXt"|b"zTXt"|b"iTXt"){self.key_start=self.at+8;self.cursor=self.key_start;self.key_length=0;self.value_length=0;self.flag=0;self.copying=false;self.utf8=Utf8::default();self.phase="keyword"}else{self.at=self.next}},
  "keyword"=>{if self.cursor==self.end{return Err(invalid("PNG text keyword separator missing"))}let b=source[self.cursor];self.cursor+=1;if b==0{self.key_end=self.cursor-1;if self.key_end==self.key_start||self.key_end-self.key_start>79{return Err(invalid("Invalid PNG text keyword"))}self.phase=if self.kind==*b"tEXt"{"value-start"}else if self.kind==*b"zTXt"{"method"}else{"flag"}}else{self.key_length+=if b<128{1}else{2}}},
  "flag"=>{if self.cursor==self.end{return Err(invalid("PNG text flag missing"))}self.flag=source[self.cursor];self.cursor+=1;if self.flag>1{return Err(invalid("Invalid PNG text compression flag"))}self.phase="method"},
  "method"=>{if self.cursor==self.end||source[self.cursor]!=0{return Err(invalid("Invalid PNG text compression method"))}self.cursor+=1;self.phase=if self.kind==*b"zTXt"{"value-start"}else{"language"}},
  "language"=>{if self.cursor==self.end{return Err(invalid("PNG text language separator missing"))}let b=source[self.cursor];self.cursor+=1;if b==0{self.phase="translated"}else if b>127{return Err(invalid("Invalid PNG text language"))}},
  "translated"=>{if self.cursor==self.end{return Err(invalid("PNG text translated separator missing"))}let b=source[self.cursor];self.cursor+=1;if b==0{self.utf8.finish()?;self.utf8=Utf8::default();self.phase="value-start"}else{self.utf8.byte(b)?}},
  "value-start"=>{self.value_start=self.cursor;if self.kind==*b"zTXt"||self.flag==1{self.start_zlib()}else{self.utf8=Utf8::default();self.phase="value"}},
  "value"=>{if self.cursor==self.end{self.after_value()?}else{let b=source[self.cursor];self.cursor+=1;self.text_byte(b)?}},
  "zlib-header"=>{if self.end.saturating_sub(self.value_start)<6||self.z_cursor>=self.end-4{return Err(invalid("Truncated PNG text zlib stream"))}self.z_header[self.z_header_at]=source[self.z_cursor];self.z_cursor+=1;self.z_header_at+=1;p.copied_bytes=1;self.partial_copy=1;if self.z_header_at==2{let [cmf,flg]=self.z_header;if cmf&15!=8||cmf>>4>7||u16::from_be_bytes([cmf,flg])%31!=0||flg&32!=0{return Err(invalid("Invalid PNG text zlib header"))}self.inflater=Some(PngInflater(Inflater::try_new_retained(1usize<<((cmf>>4)+8),32768).map_err(|_|invalid("PNG text inflater refused"))?));p.copied_bytes+=size_of::<PngInflater>();self.phase="inflate"}},
  "inflate"=>{let owner=self.inflater.as_mut().unwrap();if owner.next_retained_allocation_bytes().is_some(){let before=owner.retained_allocated_bytes();match owner.reserve_retained_history(grant.maximum_capacity_bytes){Ok(step)=>{self.partial_capacity=step.allocated_bytes;self.owned+=step.allocated_bytes;if step.allocated_bytes>grant.maximum_capacity_bytes||self.owned>self.maximum{return Err(invalid("PNG text inflater exceeded its grant"))}p.retained_capacity_bytes=step.allocated_bytes},Err(error)=>{self.partial_capacity=error.allocated_bytes.saturating_sub(before);self.owned+=self.partial_capacity;return Err(invalid("PNG text inflater allocation refused"))}}}else{p.copied_bytes=size_of::<PngInflater>();if self.pending.is_none()&&self.z_cursor<self.end-4{self.pending=Some(source[self.z_cursor]);self.z_cursor+=1;p.copied_bytes+=1}self.partial_copy=p.copied_bytes;match owner.advance(&mut self.pending,self.z_cursor==self.end-4).map_err(|_|invalid("Invalid PNG text DEFLATE stream"))?{InflateOutcome::NeedInput=>{},InflateOutcome::Wrote(b)=>{self.adler_a=(self.adler_a+b as u32)%65521;self.adler_b=(self.adler_b+self.adler_a)%65521;let before=self.value.len();self.text_byte(b)?;p.copied_bytes+=self.value.len()-before},InflateOutcome::Done=>{if self.pending.is_some()||self.z_cursor!=self.end-4||owner.terminal_unused_bytes()!=Some(0)||be(source,self.end-4)!=(self.adler_b<<16|self.adler_a){return Err(invalid("PNG text zlib checksum or extent invalid"))}if self.kind==*b"iTXt"{self.utf8.finish()?}self.phase="inflate-close"}}}},
  "inflate-close"=>{let owner=self.inflater.as_mut().unwrap();if owner.retained_terminal_is_empty(){self.inflater=None;self.after_value()?}else{let step=owner.close_retained_step(grant.maximum_items,grant.maximum_release_bytes);let work=owner.last_retained_close_work();self.last_work=work;p.copied_items=usize::from(work!=0);if let RetainedInflateCloseStep::Pending{released_bytes,..}=step{p.released_bytes=released_bytes;self.owned=self.owned.saturating_sub(released_bytes)}}},
  "key-allocation"=>{let n=Self::reserve(&mut self.key,self.key_length)?;self.partial_capacity=n;self.owned+=n;if n>grant.maximum_capacity_bytes||self.owned>self.maximum{return Err(invalid("PNG text key allocation exceeded its grant"))}p.retained_capacity_bytes=n;self.phase="value-allocation"},
  "value-allocation"=>{let n=Self::reserve(&mut self.value,self.value_length)?;self.partial_capacity=n;self.owned+=n;if n>grant.maximum_capacity_bytes||self.owned>self.maximum{return Err(invalid("PNG text value allocation exceeded its grant"))}p.retained_capacity_bytes=n;self.cursor=self.key_start;self.phase="copy-key"},
  "copy-key"=>{if self.cursor==self.key_end{self.copying=true;self.cursor=self.value_start;if self.kind==*b"zTXt"||self.flag==1{self.start_zlib()}else{self.utf8=Utf8::default();self.phase="copy-value"}}else{let b=source[self.cursor];self.cursor+=1;if b<128{self.key.push(b);p.copied_bytes=1}else{self.key.push(0xc0|(b>>6));self.key.push(0x80|(b&63));p.copied_bytes=2}}},
  "copy-value"=>{if self.cursor==self.end{self.after_value()?}else{let b=source[self.cursor];self.cursor+=1;let before=self.value.len();self.text_byte(b)?;p.copied_bytes=self.value.len()-before}},
  "emit"=>{if self.key.len()!=self.key_length||self.value.len()!=self.value_length{return Err(invalid("PNG text replay extent changed"))}let key=unsafe{String::from_utf8_unchecked(std::mem::take(&mut self.key))};let value=unsafe{String::from_utf8_unchecked(std::mem::take(&mut self.value))};self.rows.push((key,value));p.copied_bytes=size_of::<(String,String)>();self.at=self.next;self.phase="chunk"},
  _=>return Err(invalid("Invalid PNG text cursor")),
 }Ok(p)}
 pub(super) fn advance(&mut self,source:&[u8],grant:RetainedCloneGrant)->Result<(bool,RetainedCloneProgress),PngDecodeError>{self.last_work=0;self.last_progress=Default::default();if let Some(error)=self.failed.as_ref(){return Err(error.clone())}let mut total=RetainedCloneProgress::default();let mut work=0;for _ in 0..grant.maximum_items{if self.done(){break}let d=self.demand()?;let remaining=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:grant.maximum_copy_bytes.saturating_sub(total.copied_bytes),maximum_capacity_bytes:grant.maximum_capacity_bytes.saturating_sub(total.retained_capacity_bytes),maximum_release_bytes:grant.maximum_release_bytes.saturating_sub(total.released_bytes),maximum_depth:grant.maximum_depth};if !semio_framework_value::retained_clone::retained_clone_grant_admits(remaining,d){break}self.partial_capacity=0;self.partial_copy=0;self.last_work=1;let p=match self.step(source,remaining){Ok(p)=>p,Err(error)=>{work+=self.last_work;self.last_work=work;total.copied_items+=1;total.copied_bytes+=self.partial_copy;total.retained_capacity_bytes+=self.partial_capacity;self.last_progress=total;self.failed=Some(error.clone());return Err(error)}};work+=self.last_work;self.last_work=work;total.copied_items+=p.copied_items;total.copied_bytes+=p.copied_bytes;total.retained_capacity_bytes+=p.retained_capacity_bytes;total.released_bytes+=p.released_bytes;self.last_progress=total;if p.copied_items==0{break}}Ok((self.done(),total))}
 pub(super) fn take(&mut self,grant:RetainedCloneGrant)->Result<Option<(Vec<(String,String)>,RetainedCloneProgress)>,PngDecodeError>{if !self.done(){return Err(PngDecodeError::Incomplete)}if grant.maximum_items==0||grant.maximum_copy_bytes<size_of::<Vec<(String,String)>>()||grant.maximum_depth==0{return Ok(None)}self.phase="transferred";Ok(Some((std::mem::take(&mut self.rows),RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Vec<(String,String)>>(),..Default::default()})))}
}
